import { Inject, Injectable, NotFoundException } from '@nestjs/common';
import type { CreateTaskDto, TaskQuery, UpdateTaskDto } from './task.dto.js';
import { TASK_REPOSITORY } from './task.repository.js';
import type { Task, TaskPage, TaskRepository } from './task.repository.js';

/** Task use cases. Generated by `nestvexa make:resource`; add authorization per record here. */
@Injectable()
export class TaskService {
  constructor(
    @Inject(TASK_REPOSITORY) private readonly repository: TaskRepository,
  ) {}
  list(query: TaskQuery): Promise<TaskPage> {
    return this.repository.list(query);
  }
  async get(id: number): Promise<Task> {
    const item = await this.repository.find(id);
    if (!item) throw new NotFoundException();
    return item;
  }
  create(input: CreateTaskDto): Promise<Task> {
    return this.repository.create(input);
  }
  async update(id: number, input: UpdateTaskDto): Promise<Task> {
    const item = await this.repository.update(id, input);
    if (!item) throw new NotFoundException();
    return item;
  }
  async remove(id: number): Promise<void> {
    if (!(await this.repository.remove(id))) throw new NotFoundException();
  }
}
